#!/usr/bin/env python3
"""Authored quest catalogue. Conditions are interpreted against existing systems."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
quests=[]
def q(ident,title,desc,goal,target=1,**kw):
 item=dict(id=ident,title=title,description=desc,objective=dict(kind=goal,target=target),reward=dict(gold=kw.pop('gold',18),prestige=kw.pop('prestige',1)),consequence=kw.pop('consequence','Успех укрепит доверие к короне; награда выдаётся только за выполненную цель.'),**kw)
 for key in ['building','resource','action','character','realm_target','field']:
  if key in item:item['objective'][key]=item.pop(key)
 quests.append(item)

